def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    amount = sum(1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites)
    if amount <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= len(sites) or j >= len(sites) or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        oi = sites[i].get('occupancy')
        oj = sites[j].get('occupancy')
        oi = 1.0 if oi is None else max(0.0, oi)
        oj = 1.0 if oj is None else max(0.0, oj)
        total += oi * oj * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
    return float(total / (0.1225 * amount))

def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    return float(v) if v is not None and v > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    edges = [(e.get('i'), e.get('j'), e.get('distance_A') or 0.0) for e in s.get('neighbors') or []]
    bonds = [(i, j, d) for i, j, d in edges if i is not None and j is not None and 0 <= i < n and 0 <= j < n and d > 0 and radii[i] > 0 and radii[j] > 0 and d < 1.35 * (radii[i] + radii[j])]
    total = 0.0
    amount = 0.0
    for i, a in enumerate(sites):
        if radii[i] <= 0 or occ[i] <= 0:
            continue
        p = props.get(a.get('element')) or {}
        group = p.get('group')
        if p.get('Z') == 1:
            reference = 1.0
        elif group is not None and 13 <= group <= 17:
            reference = float(min(group - 10, 18 - group))
        else:
            continue
        coordination = sum(occ[j] * ((1.35 - d / (radii[i] + radii[j])) / 0.35) ** 2 for ii, j, d in bonds if ii == i)
        deficit = max(0.0, 1.0 - coordination / reference)
        total += occ[i] * deficit * deficit
        amount += occ[i]
    return float(total / amount) if amount > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    p = [props.get(a.get('element')) or {} for a in sites]
    radii = [a.get('covalent_radius_A') or 0.0 for a in p]
    eneg = [a.get('eneg') for a in p]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    amount = sum(occ[i] for i in range(n) if radii[i] > 0 and eneg[i] is not None)
    if amount <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0 or eneg[i] is None or eneg[j] is None:
            continue
        contact = max(0.0, (1.35 - d / (radii[i] + radii[j])) / 0.35)
        total += occ[i] * occ[j] * contact * contact * (eneg[i] - eneg[j]) ** 2
    return float(total / amount)

